		}
	}

	// Where checkpoint data syncs (the single elected remote), and how many
	// checkpoints have not reached it yet. Local-only computation.
	if s.Enabled {
		writeCheckpointSyncLines(ctx, &b, s, sty)
	}

	if s.Enabled {
		writeSecretScannersLine(&b, s, sty)
	}
